<?php require_once __DIR__.'/../config/auth.php';require_role('boss');$pdo=db();$branch=(int)($_GET['branch']??0);$sql='SELECT a.*,u.name user_name,b.name branch FROM audit_logs a JOIN users u ON u.id=a.user_id LEFT JOIN branches b ON b.id=a.branch_id WHERE 1=1';$args=[];if($branch){$sql.=' AND a.branch_id=?';$args[]=$branch;}$sql.=' ORDER BY a.id DESC LIMIT 300';$s=$pdo->prepare($sql);$s->execute($args);$rows=$s->fetchAll();$branches=$pdo->query('SELECT id,name FROM branches ORDER BY name')->fetchAll();$pageTitle='Audit Aktivitas';$active='audit';include __DIR__.'/../includes/header.php';?><section class="card"><form class="filter-row"><label>Cabang<select name="branch"><option value="0">Semua cabang</option><?php foreach($branches as $b):?><option value="<?=$b['id']?>" <?=$branch===$b['id']?'selected':''?>><?=e($b['name'])?></option><?php endforeach;?></select></label><button class="btn primary">Tampilkan</button></form><div class="table-wrap"><table class="table"><thead><tr><th>Waktu</th><th>Cabang</th><th>Pengguna</th><th>Aktivitas</th><th>Data</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=date('d/m/Y H:i:s',strtotime($r['created_at']))?></td><td><?=e($r['branch']??'Pusat')?></td><td><?=e($r['user_name'])?></td><td><?=e($r['action'].' · '.$r['entity'])?></td><td><small><?=e($r['after_data']?:$r['before_data'])?></small></td></tr><?php endforeach;?></tbody></table><?php if(!$rows):?><div class="empty-state">Belum ada aktivitas tercatat.</div><?php endif;?></div></section><?php include __DIR__.'/../includes/footer.php';?>
